create table if not exists schools (id integer primary key, name text not null unique, email_domain text not null unique);
create table if not exists users (id text primary key, email text not null unique, name text not null, pronoun text, school_id integer not null references schools(id), school_year text not null check (school_year in ('first','second','third','fourth','fourth+','graduate')), major text, hobbies jsonb not null default '[]', interested_types jsonb not null default '[]', created_at timestamptz not null default now());
create table if not exists activities (id text primary key, creator_id text not null references users(id) on delete cascade, school_id integer not null references schools(id), name text not null, description text not null default '', type text not null check (type in ('study','food','sports','career','other')), location text not null, start_time timestamptz not null, end_time timestamptz not null, link text, deleted_at timestamptz, created_at timestamptz not null default now(), check(end_time > start_time));
create table if not exists join_requests (id text primary key, activity_id text not null references activities(id) on delete cascade, user_id text not null references users(id) on delete cascade, status text not null default 'pending' check(status in ('pending','accepted','rejected')), created_at timestamptz not null default now(), unique(activity_id,user_id));
insert into schools(id,name,email_domain) values (1,'University of British Columbia','student.ubc.ca'),(2,'Simon Fraser University','sfu.ca'),(3,'University of Victoria','uvic.ca') on conflict do nothing;
